func Plan(g *Game) string {
	best, bestV := "tick", 0.0
	path := g.Path()
	for _, c := range g.LegalMoves() {
		f := strings.Fields(c)
		if f[0] != "build" || f[1] == "frost" {
			continue
		}
		x, _ := strconv.Atoi(f[2])
		y, _ := strconv.Atoi(f[3])
		rng, cost := 2, 6.0
		if f[1] == "mortar" {
			rng, cost = 3, 12.0
		}
		cov := 0
		for i := 1; i < len(path)-1; i++ {
			dx, dy := path[i][0]-x, path[i][1]-y
			if dx < 0 {
				dx = -dx
			}
			if dy < 0 {
				dy = -dy
			}
			if dx+dy <= rng {
				cov++
			}
		}
		v := float64(cov) / cost
		if f[1] == "arrow" {
			v += 0.05
		}
		if f[1] == "mortar" && g.TowerCount("arrow") < 3 {
			v -= 1
		}
		if v > bestV {
			best, bestV = c, v
		}
	}
	return best
