		return fmt.Sprintf("built %s %d,%d -%d", f[1], x, y, st.cost), nil
	case "sell":
		x, _ := strconv.Atoi(f[1])
		y, _ := strconv.Atoi(f[2])
		t := g.towerAt(x, y)
		refund := towerStats[t.kind].cost * sellPercent / 100
		g.gold += refund
		for i, tt := range g.towers {
